var blobs=[];var colors;let variation=0;let xScale,yScale,centerX,centerY;let canvas;let sketchReady=false;let pauseRequestedByCard2=false;let changeDuration=3000;let lastChange=0;function setup(){canvas=createCanvas(window.visualViewport.width,window.visualViewport.height);canvas.position(0,0);canvas.style('z-index','-1');canvas.style('position','fixed');textAlign(CENTER,CENTER);xScale=width/20;yScale=height/20*(width/height);centerX=width/2;centerY=height/2;sketchReady=true;colors=[color("#010027"),color("#000dff"),color("#0091ff"),color("#00124c"),color("#001e95")];if(pauseRequestedByCard2){noLoop();}}function setSketchPausedByCard2(shouldPause){pauseRequestedByCard2=shouldPause;if(!sketchReady||typeof isLooping!=="function"){return;}if(shouldPause){if(isLooping()){noLoop();}return;}if(!isLooping()){loop();}}function initCard2SketchObserver(){if(typeof IntersectionObserver!=="function"){return;}const card2Elements=document.querySelectorAll("#card2");if(!card2Elements.length){return;}const visibleCard2=new Set();const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting&&entry.intersectionRatio>=0.35){visibleCard2.add(entry.target);}else{visibleCard2.delete(entry.target);}});setSketchPausedByCard2(visibleCard2.size>0);},{threshold:[0,0.35,0.6]});card2Elements.forEach((card)=>observer.observe(card));}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initCard2SketchObserver);}else{initCard2SketchObserver();}function draw(){if(mouseX){for(let i=0;i<1;i++){let x=mouseX+random(-100,100);let y=mouseY+random(-100,100);var blob={x:getXPos(x),y:getYPos(y),size:random(1,5),lastX:x,lastY:y,color:colors[floor(random(colors.length))],direction:random(0.1,1)*(random()>0.5?1:-1)};blobs.push(blob);}}var length=blobs.length;if(length==0){background("#000000");noStroke();fill(255);textSize(30);return;}noStroke();fill(0,0,0,12);rect(0,0,width,height);let time=millis();if(time-lastChange>changeDuration){lastChange=time;variation++;if(variation>11)variation=0;}var stepsize=deltaTime*0.002;for(var i=length-1;i>=0;i--){let blob=blobs[i];var x=getSlopeX(blob.x,blob.y);var y=getSlopeY(blob.x,blob.y);blob.x+=blob.direction*x*stepsize;blob.y+=blob.direction*y*stepsize;x=getXPrint(blob.x);y=getYPrint(blob.y);stroke(blob.color);strokeWeight(blob.size);line(x,y,blob.lastX,blob.lastY);blob.lastX=x;blob.lastY=y;const border=200;if(x<-border||y<-border||x>width+border||y>height+border){blobs.splice(i,1);}}}function getSlopeY(x,y){switch(variation){case 0:return Math.sin(x);case 1:return Math.sin(x*5)*y*0.3;case 2:return Math.cos(x*y);case 3:return Math.sin(x)*Math.cos(y);case 4:return Math.cos(x)*y*y;case 5:return Math.log(Math.abs(x))*Math.log(Math.abs(y));case 6:return Math.tan(x)*Math.cos(y);case 7:return-Math.sin(x*0.1)*3;case 8:return(x-x*x*x)*0.01;case 9:return-Math.sin(x);case 10:return-y-Math.sin(1.5*x)+0.7;case 11:return Math.sin(x)*Math.cos(y);}}function getSlopeX(x,y){switch(variation){case 0:return Math.cos(y);case 1:return Math.cos(y*5)*x*0.3;case 2:case 3:case 4:case 5:case 6:return 1;case 7:return Math.sin(y*0.1)*3;case 8:return y/3;case 9:return-y;case 10:return-1.5*y;case 11:return Math.sin(y)*Math.cos(x);}}function getXPos(x){return(x-centerX)/xScale;}function getYPos(y){return(y-centerY)/yScale;}function getXPrint(x){return xScale*x+centerX;}function getYPrint(y){return yScale*y+centerY;}window.visualViewport.addEventListener('resize',()=>{resizeCanvas(window.visualViewport.width,window.visualViewport.height);});